    for (int i = 0; i < 20; ++i)
        h.coordinator.pump();
    CHECK(h.coordinator.find(started.action_id)->state == ToolState::Running);
    CHECK(h.workspace.slice_starts == 1);

    // A read submitted meanwhile still runs.
