void ToolExecutionCoordinator::finish_slice_waits(const Workspace::WorkspaceSnapshot& snapshot, bool overdue)
{
    const auto now = m_clock();
    for (auto wait = m_slice_waits.begin(); wait != m_slice_waits.end();) {
        ToolActivity* activity = find_mutable(wait->first);
        if (activity == nullptr || activity->state != ToolState::Running) {
            wait = m_slice_waits.erase(wait);
            continue;
        }
        if (overdue && now < wait->second.deadline) {
            ++wait;
            continue;
        }
        if (snapshot.session.value() != activity->session) {
            const std::string action = wait->first;
            wait = m_slice_waits.erase(wait);
            fail(*find_mutable(action), "stale_revision", "The project changed while it was slicing.");
            continue;
        }
        std::optional<Workspace::SliceFailure> failure;
        const bool sliced = targets_sliced(snapshot, wait->second.plate, failure);
        json result{{"handle", activity->action_id}, {"started", true}, {"finished", sliced},
                    {"slicing", slicing_section_result(snapshot, m_slice_handle)},
                    {"sessionId", std::to_string(snapshot.session.value())}, {"revision", snapshot.revision}};
        if (failure)
            result["reason"] = slice_failure_result(*failure);
        activity->result_json = result.dump();
        activity->state       = ToolState::Succeeded;
        const std::string action = wait->first;
        wait = m_slice_waits.erase(wait);
        notify(*find_mutable(action));
    }
}

