    const std::string action =
        h.coordinator.submit({"slice_start", json{{"plateId", std::to_string(plate.value())}, {"wait", true}}.dump()}, "m-1").action_id;
    for (int i = 0; i < 20; ++i)
        h.coordinator.pump();
    REQUIRE(h.workspace.slice_starts == 1);
    REQUIRE(h.coordinator.find(action)->state == ToolState::Running);

    SECTION("the run ends: the change finishes the call, with no tick")
    {
        h.workspace.finish_slice_for_testing(true);
        const ToolActivity done = *h.coordinator.find(action);
        REQUIRE(done.state == ToolState::Succeeded);
        const json result = json::parse(done.result_json);
        CHECK(registry.validate_output(*registry.find("slice_start"), result));
        CHECK(result["finished"] == true);
        CHECK_FALSE(result.contains("reason"));
    }

    SECTION("the run fails: the call finishes with the failure")
    {
        Workspace::SliceFailure failure;
        failure.severity = "blocker";
