        REQUIRE(done.state == ToolState::Succeeded);
        const json result = json::parse(done.result_json);
        CHECK(registry.validate_output(*registry.find("slice_start"), result));
        CHECK(result["started"] == true);
        CHECK(result["finished"] == false);
        CHECK(result["reason"] == json{{"kind", "failed"}, {"severity", "blocker"}, {"message", failure.message}});
    }

    SECTION("the run never reports: the deadline finishes the call")
    {
        now += std::chrono::minutes(14);
        h.coordinator.pump();
        CHECK(h.coordinator.find(action)->state == ToolState::Running);
        now += std::chrono::minutes(2);
        h.coordinator.pump();
        const ToolActivity done = *h.coordinator.find(action);
        REQUIRE(done.state == ToolState::Succeeded);
        const json result = json::parse(done.result_json);
        CHECK(registry.validate_output(*registry.find("slice_start"), result));
        CHECK(result["finished"] == false);
        CHECK(result["slicing"]["running"] == true);
    }
}

