    expect((sent[0].payload as { skills: { trigger: string }[] }).skills.map((skill) => skill.trigger))
      .toContain('model_arrived');
  });

  it('draws no file report the Agent is speaking about', () => {
    render(<App getTransport={() => host.transport} />);
    connect(host);
